INSERT INTO personagem_tripulacao (personagem_id, tripulacao_id, cargo_id, data_entrada)
SELECT
  personagem.id     AS personagem_id,
  tripulacao.id     AS tripulacao_id,
  cargo.id          AS cargo_id,
  dado.data_entrada AS data_entrada
FROM (
  VALUES
    ROW('A O', 'Piratas A O', 'Capitão', NULL),
    ROW('Abdullah', 'Piratas do Ideo', NULL, NULL),
    ROW('Absalom', 'Piratas de Thriller Bark', NULL, NULL),
